INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die doppelte Buchführung für alle Unternehmen Pflicht?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Unternehmen können einfach buchen"}, {"text": "Ja", "correct": false, "because": "Nicht gesetzlich für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Buchhaltung?', 3, '[{"text": "Transparenz der Finanzen", "correct": true, "because": "Übersicht über Vermögen und Schulden"}, {"text": "Steigerung der Verkäufe", "correct": false, "because": "Nicht primär"}, {"text": "Mitarbeitermotivation", "correct": false, "because": "Kein direkter Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile gehören zur Bilanz?', 5, '[{"text": "Aktiva", "correct": true, "because": "Vermögenswerte"}, {"text": "Passiva", "correct": true, "because": "Schulden und Eigenkapital"}, {"text": "Umsatzprognosen", "correct": false, "because": "Zukunftsorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Gewinn- und Verlustrechnung zeigt den Jahresüberschuss. b) Sie ist Teil der Bilanz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GuV ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Erstellung einer Bilanz?', 4, '[{"text": "Vermögenswerte", "correct": false, "because": "Kern der Aktiva"}, {"text": "Verbindlichkeiten", "correct": false, "because": "Teil der Passiva"}, {"text": "Firmenfarben", "correct": true, "because": "Irrelevant für Finanzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Soll und Haben immer gleich sein müssen?', 2, '[{"text": "Ja", "correct": true, "because": "Grundprinzip der doppelten Buchführung"}, {"text": "Nein", "correct": false, "because": "Bilanz muss ausgeglichen sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für die Erfassung von Geschäftsvorfällen?', 3, '[{"text": "Doppelte Buchführung", "correct": true, "because": "Standard für Genauigkeit"}, {"text": "Einzelbuchhaltung", "correct": false, "because": "Weniger detailliert"}, {"text": "Schätzung", "correct": false, "because": "Nicht präzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Finanzbuchhaltung?', 5, '[{"text": "Erfassung von Einnahmen", "correct": true, "because": "Teil der Geschäftsvorfälle"}, {"text": "Buchung von Ausgaben", "correct": true, "because": "Vollständigkeit der Daten"}, {"text": "Marktforschung", "correct": false, "because": "Kein Buchhaltungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Abschreibungen reduzieren den Gewinn. b) Sie sind optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abschreibungen sind Pflicht bei Anlagen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Buchhaltung unwichtig?', 4, '[{"text": "Kontoauszüge", "correct": false, "because": "Basis der Erfassung"}, {"text": "Rechnungen", "correct": false, "because": "Belege nötig"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Einfluss auf Zahlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Bilanz ein Momentaufnahme?', 2, '[{"text": "Ja", "correct": true, "because": "Stand zu einem Stichtag"}, {"text": "Nein", "correct": false, "because": "Nicht über Periode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine genaue Buchhaltung?', 4, '[{"text": "Steuerliche Korrektheit", "correct": true, "because": "Vermeidet Probleme"}, {"text": "Transparenz für Investoren", "correct": true, "because": "Vertrauen schaffen"}, {"text": "Höhere Umsätze", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Buchhaltung nur historische Daten zeigt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Vergangenheit"}, {"text": "Nein", "correct": false, "because": "Aber Basis für Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Jahresabschlusserstellung?', 3, '[{"text": "Richtigkeit", "correct": true, "because": "Vermeidet Fehler"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt mehr"}, {"text": "Präsentation", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eigenkapital ist Teil der Passiva. b) Umsatzerlöse sind Vermögen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Umsatzerlöse sind GuV"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine schlechte Buchhaltung?', 5, '[{"text": "Fehlerhafte Steuererklärungen", "correct": true, "because": "Falsche Daten"}, {"text": "Verlust von Vertrauen", "correct": true, "because": "Investoren skeptisch"}, {"text": "Geringere Kosten", "correct": false, "because": "Kosten steigen durch Nacharbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der GuV unwichtig?', 3, '[{"text": "Erträge", "correct": false, "because": "Kernbestandteil"}, {"text": "Aufwendungen", "correct": false, "because": "Entscheidend für Gewinn"}, {"text": "Firmengröße", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Abschreibungen jährlich erfolgen?', 3, '[{"text": "Ja", "correct": true, "because": "Regelmäßige Wertminderung"}, {"text": "Nein", "correct": false, "because": "Pflicht bei Anlagen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Buchhaltung auch Planung umfasst?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus auf Vergangenheit"}, {"text": "Ja", "correct": false, "because": "Daten für Planung genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterlagen brauche ich für die Buchhaltung?', 4, '[{"text": "Belege", "correct": true, "because": "Nachweis der Vorfälle"}, {"text": "Kontoauszüge", "correct": true, "because": "Banktransaktionen"}, {"text": "Mitarbeiterfotos", "correct": false, "because": "Irrelevant"}]');
